Here is a custom React hook for tracking window resize:

```jsx
import { useState, useEffect } from "react";

function useWindowSize() {
  const [windowSize, setWindowSize] = useState({
    width: window.innerWidth,
    height: window.innerHeight,
  });

  useEffect(() => {
    function handleResize() {
      setWindowSize({
        width: window.innerWidth,
        height: window.innerHeight,
      });
    }

    // Debounce for performance
    let timeoutId;
    function debouncedHandleResize() {
      clearTimeout(timeoutId);
      timeoutId = setTimeout(handleResize, 100);
    }

    window.addEventListener("resize", debouncedHandleResize);
    handleResize(); // Get initial size

    return () => {
      window.removeEventListener("resize", debouncedHandleResize);
      clearTimeout(timeoutId);
    };
  }, []);

  return windowSize;
}

// Usage
export default function App() {
  const { width, height } = useWindowSize();

  return (
    <div>
      <p>Window: {width} x {height}</p>
      {width < 768 ? <MobileView /> : <DesktopView />}
    </div>
  );
}
```

The hook returns the current window dimensions and updates on resize with debouncing for performance. Common uses: responsive rendering, conditional layouts, and adapting component behavior based on viewport size.
